description:
Implement a `useInput` hook for controlled inputs that returns `{ value, onChange, reset }`. `onChange` must accept a React change event and update `value` from `e.target.value`. `reset` restores the initial value.

**Example:**
```tsx
const { value, onChange, reset } = useInput('');
// <input value={value} onChange={onChange} />
```

starter_code:
import { useState } from 'react';

export function useInput(initial = '') {
  // your code here
}

test_suite:
test('starts at initial value', () => {
  const { result } = renderHook(() => useInput('hello'));
  expect(result.current.value).toBe('hello');
});

test('onChange updates value from e.target.value', () => {
  const { result } = renderHook(() => useInput(''));
  act(() => result.current.onChange({ target: { value: 'world' } }));
  expect(result.current.value).toBe('world');
});

test('reset restores initial value', () => {
  const { result } = renderHook(() => useInput('init'));
  act(() => result.current.onChange({ target: { value: 'changed' } }));
  act(() => result.current.reset());
  expect(result.current.value).toBe('init');
});

test('empty string default', () => {
  const { result } = renderHook(() => useInput());
  expect(result.current.value).toBe('');
});

// __hidden__
test('multiple onChange calls accumulate correctly', () => {
  const { result } = renderHook(() => useInput(''));
  act(() => result.current.onChange({ target: { value: 'a' } }));
  act(() => result.current.onChange({ target: { value: 'ab' } }));
  expect(result.current.value).toBe('ab');
});

solution:
import { useState } from 'react';

export function useInput(initial = '') {
  const [value, setValue] = useState(initial);
  return {
    value,
    onChange: (e) => setValue(e.target.value),
    reset: () => setValue(initial),
  };
}
